// Stable IDs preserve old N4 example content while adding a structured course.
for(const [ui,u] of N4_UNITS.entries()){for(const [gi,g]of u.grammar.entries()){const n=(ui+gi)%g.options.length;g.options=[...g.options.slice(n),...g.options.slice(0,n)];g.answer=(g.answer-n+g.options.length)%g.options.length;}for(const k of ['reading','listening']){const t=u[k],n=ui%t.options.length;t.options=[...t.options.slice(n),...t.options.slice(0,n)];t.answer=(t.options.length-n)%t.options.length;}u.wordIds=u.vocab.map((v,i)=>{const [word,reading,meaning,pos]=v;let w=words.find(w=>w.level==='N4'&&w.word===word&&w.reading===reading);if(!w){w={id:u.id+'w'+i,level:'N4',word,reading,meaning,pos};words.push(w);}return w.id;});u.grammarIds=u.grammar.map(g=>{grammar.push({...g,level:'N4',topic:u.title,desc:g.rule.split('。')[0]+'。',tip:g.pitfall,examples:g.examples.map(e=>[e[0],e[1]+' / '+e[2]])});return g.id;});for(const [k,arr,type]of [['reading',readings,'r'],['listening',listenings,'l']]){u[k].id=u.id+k;arr.push({...u[k],id:u[k].id,level:'N4',type,title:u.title,q:u[k].q,answer:u[k].answer,why:u[k].translation,unit:u.id});}}
